         {'workspace': STRING, 'model': MODEL, 'thought_level': STRING, 'caller_permission_mode': CALLER,
          'transport': {'type': 'string', 'enum': ['desktop_native']},
          'attach_report_mcp': BOOL,
          'workflow_mode': {'type': 'string', 'enum': ['disabled', 'onDemand', 'alwaysOn']}, 'label': STRING},
